# BK: ask allow_apply() before the applicant's own row on the FORM, which is the third decision
# surface. A method that stops taking applications then refuses everybody who already applied
# with "Enrolment is disabled or inactive" - a fact about somebody else's problem.
s|        \$ownrow = \$DB->get_record\(\n            'user_enrolments',\n            \['userid' => \$USER->id, 'enrolid' => \$instance->id\],\n            'id, status',\n            IGNORE_MULTIPLE\n        \);\n        if \(\$ownrow\) \{\n            throw new \\moodle_exception\(\n                \\enrol_apply\\local\\applicantstate::message_key\(\$ownrow, \$hasaccess\),\n                'enrol_apply'\n            \);\n        \}\n\n        \$allowapply = \$this->get_plugin\(\)->allow_apply\(\$instance\);\n        if \(\$allowapply !== true\) \{\n            throw new \\moodle_exception\('cantenrol', 'enrol_apply'\);\n        \}|        \$allowapply = \$this->get_plugin()->allow_apply(\$instance);\n        if (\$allowapply !== true) {\n            throw new \\moodle_exception('cantenrol', 'enrol_apply');\n        }\n\n        \$ownrow = \$DB->get_record(\n            'user_enrolments',\n            ['userid' => \$USER->id, 'enrolid' => \$instance->id],\n            'id, status',\n            IGNORE_MULTIPLE\n        );\n        if (\$ownrow) {\n            throw new \\moodle_exception(\n                \\enrol_apply\\local\\applicantstate::message_key(\$ownrow, \$hasaccess),\n                'enrol_apply'\n            );\n        }|s;
